import{_ as a,o as p,c as r,a2 as i}from"./chunks/framework.EUByU7Iq.js";const g=JSON.parse('{"title":"《佛经 · 阿弥陀经》","description":"","frontmatter":{"title":"《佛经 · 阿弥陀经》","date":"2026-11-23T00:00:00.000Z","categories":["美文","佛经"],"collection":"《佛经 · 阿弥陀经》","tags":["佛经","姚秦"],"poem":true,"poem_quote":false,"merged":true,"pieces":1,"author":"鸠摩罗什 译","source_book":"佛经"},"headers":[],"relativePath":"blogs/佛经·阿弥陀经/index.md","filePath":"blogs/佛经·阿弥陀经/index.md"}'),l={name:"blogs/佛经·阿弥陀经/index.md"};function c(u,s,d,t,e,o){return p(),r("div",null,[...s[0]||(s[0]=[i('<h1 id="《佛经-·-阿弥陀经》" tabindex="-1">《佛经 · 阿弥陀经》 <a class="header-anchor" href="#《佛经-·-阿弥陀经》" aria-label="Permalink to &quot;《佛经 · 阿弥陀经》&quot;">​</a></h1><p class="poem-meta">姚秦 · 鸠摩罗什 译</p><p>全文 20 段，经文与白话逐段对照，收录完整。</p><div class="merged-book"><h3 id="佛说阿弥陀经" tabindex="-1">佛说阿弥陀经 <a class="header-anchor" href="#佛说阿弥陀经" aria-label="Permalink to &quot;佛说阿弥陀经&quot;">​</a></h3><div class="sutra"><div class="su-pair"><p class="su-org">如是我闻：</p><p class="su-tra">这部经是我亲耳听佛说的。</p></div><div class="su-pair"><p class="su-org">一时，佛在舍卫国衹树给孤独园，与大比丘僧千二百五十人俱，皆是大阿罗汉，众所知识。长老舍利弗、摩诃目犍连、摩诃迦叶、摩诃迦旃延、摩诃俱絺罗、离婆多、周利槃陀伽、难陀、阿难陀、罗睺罗、憍梵波提、宾头卢颇罗堕、迦留陀夷、摩诃劫宾那、薄拘罗、阿㝹楼驮，如是等诸大弟子。并诸菩萨摩诃萨——文殊师利法王子、阿逸多菩萨、干陀诃提菩萨、常精进菩萨——与如是等诸大菩萨，及释提桓因等无量诸天大众俱。</p><p class="su-tra">那时候，佛住在舍卫国祇树给孤独园，和一千二百五十位大比丘僧在一起，这些都是大阿罗汉，是大家都认识的：长老舍利弗、摩诃目犍连、摩诃迦叶、摩诃迦旃延、摩诃俱絺罗、离婆多、周利槃陀伽、难陀、阿难陀、罗睺罗、憍梵波提、宾头卢颇罗堕、迦留陀夷、摩诃劫宾那、薄拘罗、阿㝹楼驮，像这样许多的上首弟子；又有文殊师利法王子、阿逸多菩萨、干陀诃提菩萨、常精进菩萨，与这样的诸大菩萨，以及释提桓因等无量诸天大众。</p></div><div class="su-pair"><p class="su-org">尔时，佛告长老舍利弗：</p><p class="su-tra">这时候，佛告诉长老舍利弗：</p></div><div class="su-pair"><p class="su-org">“从是西方过十万亿佛土，有世界名曰极乐。其土有佛，号阿弥陀。今现在说法。舍利弗！彼土何故名为极乐？其国众生无有众苦，但受诸乐，故名极乐。又舍利弗！极乐国土，七重栏楯、七重罗网、七重行树，皆是四宝周帀围绕，是故彼国名为极乐。”</p><p class="su-tra">“从这里往西方，越过十万亿佛土，有个世界名叫极乐。那地方有佛，号阿弥陀，现在正在说法。舍利弗！那国土为什么叫极乐？那国的众生没有一点苦，只受种种乐，所以叫极乐。还有，舍利弗！极乐国土有七重栏杆、七重宝网、七重行树，都是金、银、琉璃、玻璃四宝所成，四面环绕，所以那国叫极乐。”</p></div><div class="su-pair"><p class="su-org">“又舍利弗！极乐国土有七宝池，八功德水充满其中，池底纯以金沙布地。四边阶道，金、银、琉璃、玻瓈、合成；上有楼阁，亦以金、银、琉璃、玻瓈、砗磲、赤珠、玛瑙而严饰之。池中莲华，大如车轮，青色青光，黄色黄光，赤色赤光，白色白光，微妙香洁。舍利弗！极乐国土成就如是功德庄严。”</p><p class="su-tra">“又，舍利弗！极乐国土有七宝造成的池子，具足八种功德的水充满其中，池底纯用金沙铺地。四边的台阶通道，也是金、银、琉璃、玻璃合成；池上有楼阁，同样用金、银、琉璃、玻璃、砗磲、赤珠、玛瑙装饰起来。池中的莲花大如车轮：青色的放青光，黄色的放黄光，赤色的放赤光，白色的放白光，精微奥妙，芬芳洁净。舍利弗！极乐国土就是这样成就了这样的功德庄严。”</p></div><div class="su-pair"><p class="su-org">“又舍利弗！彼佛国土，常作天乐，黄金为地，昼夜六时，雨天曼陀罗华。其土众生，常以清旦，各以衣裓盛众妙华，供养他方十万亿佛；即以食时，还到本国，饭食经行。舍利弗！极乐国土成就如是功德庄严。”</p><p class="su-tra">“又，舍利弗！那佛的国土常常自然有天乐鸣响，地面是黄金造成的，昼夜六个时段天上落下曼陀罗花。那国的众生常在清早，各自用衣襟盛了种种妙花，去供养他方十万亿佛；就到吃早饭的时候，已经回到本国，吃饭、经行。舍利弗！极乐国土就是这样成就了这样的功德庄严。”</p></div><div class="su-pair"><p class="su-org">“复次舍利弗！彼国常有种种奇妙杂色之鸟——白鹤、孔雀、鹦鹉、舍利、迦陵频伽、共命之鸟。是诸众鸟，昼夜六时出和雅音，其音演畅五根、五力、七菩提分、八圣道分如是等法。其土众生闻是音已，皆悉念佛、念法、念僧。舍利弗！汝勿谓此鸟实是罪报所生。所以者何？彼佛国土无三恶道。舍利弗！其佛国土尚无三恶道之名，何况有实？是诸众鸟，皆是阿弥陀佛欲令法音宣流，变化所作。舍利弗！彼佛国土微风吹动，诸宝行树及宝罗网出微妙音，譬如百千种乐同时俱作，闻是音者，自然皆生念佛念法念僧之心。舍利弗！其佛国土成就如是功德庄严。”</p><p class="su-tra">“再，舍利弗！那国里常常有种种奇妙杂色的鸟——白鹤、孔雀、鹦鹉、舍利、迦陵频伽、共命之鸟。这些鸟昼夜六个时段发出和雅的声音，音声里演说五根、五力、七菩提分、八圣道分这一类的法。那国的众生听了这声音，全都生起念佛、念法、念僧的心。舍利弗！你不要以为这些鸟真是罪业果报生出来的。为什么？那佛的国土没有三恶道。舍利弗！那佛的国土连三恶道的名字都没有，何况真有恶道？这些鸟，都是阿弥陀佛要让法音宣流，变化所作。舍利弗！那佛的国土微风吹动众宝行树和宝网，发出微妙的声音，好比百千种乐器同时奏响，听到这声音的人，自然都生起念佛、念法、念僧的心。舍利弗！那佛的国土就是这样成就了这样的功德庄严。”</p></div><div class="su-pair"><p class="su-org">“舍利弗，于汝意云何？彼佛何故号阿弥陀？舍利弗！彼佛光明无量，照十方国无所障碍，是故号为阿弥陀。又舍利弗！彼佛寿命及其人民。无量无边阿僧祇劫，故名阿弥陀。舍利弗！阿弥陀佛成佛以来，于今十劫。又舍利弗！彼佛有无量无边声闻弟子，皆阿罗汉，非是算数之所能知；诸菩萨众，亦复如是。舍利弗！彼佛国土成就如是功德庄严。”</p><p class="su-tra">“舍利弗！你的意思怎么样？那佛为什么号阿弥陀？舍利弗！那佛的光明无量，照十方国无所障碍，所以号为阿弥陀。又，舍利弗！那佛的寿命以及他国土人民的寿命，是无量无边的阿僧祇劫，所以名为阿弥陀。舍利弗！阿弥陀佛成佛以来，到现在已经十劫。又，舍利弗！那佛有无量无边的声闻弟子，都是阿罗汉，不是算数所能算得清的；诸菩萨众也同样是多到算不清。舍利弗！那佛的国土就是这样成就了这样的功德庄严。”</p></div><div class="su-pair"><p class="su-org">“又舍利弗！极乐国土众生生者，皆是阿鞞跋致。其中多有一生补处，其数甚多，非是算数所能知之，但可以无量无边阿僧祇说。舍利弗！众生闻者，应当发愿，愿生彼国。所以者何？得与如是诸上善人俱会一处。”</p><p class="su-tra">“又，舍利弗！极乐国里往生的人，都是阿鞞跋致——不会再退转的。其中很多是一生就可以补佛位的，数目多到不是算数所能知道，只能用无量无边阿僧祇来比方。舍利弗！众生听说了这些，应当发愿，愿生那国。为什么？因为能与这样许多的上善之人聚在一处。”</p></div><div class="su-pair"><p class="su-org">“舍利弗！不可以少善根福德因缘得生彼国。舍利弗！若有善男子、善女人，闻说阿弥陀佛，执持名号，若一日、若二日、若三日、若四日、若五日、若六日、若七日，一心不乱。其人临命终时，阿弥陀佛与诸圣众，现在其前。是人终时，心不颠倒。即得往生阿弥陀佛极乐国土。舍利弗！我见是利，故说此言。若有众生闻是说者，应当发愿生彼国土。”</p><p class="su-tra">“舍利弗！不能凭很少的善根福德因缘就生到那国去。舍利弗！如果有善男子、善女人，听到说阿弥陀佛便执持名号，或者一天、或者两天、三天、四天、五天、六天、七天，一心不乱，这人临命终的时候，阿弥陀佛与诸圣众就现在他面前。这人命终那一刻心不颠倒，当即就得以往生阿弥陀佛的极乐国土。舍利弗！我看见了这样的利益，所以这样说。若有众生听了我这话，应当发愿生彼国土。”</p></div><div class="su-pair"><p class="su-org">“舍利弗！如我今者，赞叹阿弥陀佛不可思议功德之利；东方亦有阿閦鞞佛、须弥相佛、大须弥佛、须弥光佛、妙音佛，如是等恒河沙数诸佛，各于其国出广长舌相，徧覆三千大千世界，说诚实言：‘汝等众生，当信是称赞不可思议功德一切诸佛所护念经。’”</p><p class="su-tra">“舍利弗！就像我现在这样赞叹阿弥陀佛不可思议的功德利益；东方也有阿閦鞞佛、须弥相佛、大须弥佛、须弥光佛、妙音佛，像这样多如恒河沙数的诸佛，各在自己那一国里现出广长舌相，遍覆三千大千世界，说诚实的话：‘你们这些众生，应当信受这部赞叹不可思议功德、一切诸佛所护念的经。’”</p></div><div class="su-pair"><p class="su-org">“舍利弗！南方世界有日月灯佛、名闻光佛、大燄肩佛、须弥灯佛、无量精进佛，如是等恒河沙数诸佛，各于其国出广长舌相，徧覆三千大千世界，说诚实言：‘汝等众生，当信是称赞不可思议功德一切诸佛所护念经。’”</p><p class="su-tra">“舍利弗！南方世界有日月灯佛、名闻光佛、大焰肩佛、须弥灯佛、无量精进佛，像这样多如恒河沙数的诸佛，各在自己那一国里现出广长舌相，遍覆三千大千世界，说诚实的话：‘你们这些众生，应当信受这部赞叹不可思议功德、一切诸佛所护念的经。’”</p></div><div class="su-pair"><p class="su-org">“舍利弗！西方世界有无量寿佛、无量相佛、无量幢佛、大光佛、大明佛、宝相佛、净光佛，如是等恒河沙数诸佛，各于其国出广长舌相，徧覆三千大千世界，说诚实言：‘汝等众生，当信是称赞不可思议功德一切诸佛所护念经。’”</p><p class="su-tra">“舍利弗！西方世界有无量寿佛、无量相佛、无量幢佛、大光佛、大明佛、宝相佛、净光佛，像这样多如恒河沙数的诸佛，各在自己那一国里现出广长舌相，遍覆三千大千世界，说诚实的话：‘你们这些众生，应当信受这部赞叹不可思议功德、一切诸佛所护念的经。’”</p></div><div class="su-pair"><p class="su-org">“舍利弗！北方世界有燄肩佛、最胜音佛、难沮佛、日生佛、网明佛，如是等恒河沙数诸佛，各于其国出广长舌相，徧覆三千大千世界，说诚实言：‘汝等众生，当信是称赞不可思议功德一切诸佛所护念经。’”</p><p class="su-tra">“舍利弗！北方世界有焰肩佛、最胜音佛、难沮佛、日生佛、网明佛，像这样多如恒河沙数的诸佛，各在自己那一国里现出广长舌相，遍覆三千大千世界，说诚实的话：‘你们这些众生，应当信受这部赞叹不可思议功德、一切诸佛所护念的经。’”</p></div><div class="su-pair"><p class="su-org">“舍利弗。下方世界有师子佛、名闻佛、名光佛、达摩佛、法幢佛、持法佛，如是等恒河沙数诸佛，各于其国出广长舌相，徧覆三千大千世界，说诚实言：‘汝等众生，当信是称赞不可思议功德一切诸佛所护念经。’”</p><p class="su-tra">“舍利弗！下方世界有师子佛、名闻佛、名光佛、达摩佛、法幢佛、持法佛，像这样多如恒河沙数的诸佛，各在自己那一国里现出广长舌相，遍覆三千大千世界，说诚实的话：‘你们这些众生，应当信受这部赞叹不可思议功德、一切诸佛所护念的经。’”</p></div><div class="su-pair"><p class="su-org">“舍利弗。上方世界有梵音佛、宿王佛、香上佛、香光佛、大燄肩佛、杂色宝华严身佛、娑罗树王佛、宝华德佛、见一切义佛、如须弥山佛，如是等恒河沙数诸佛，各于其国出广长舌相，徧覆三千大千世界，说诚实言：‘汝等众生，当信是称赞不可思议功德一切诸佛所护念经。’”</p><p class="su-tra">“舍利弗！上方世界有梵音佛、宿王佛、香上佛、香光佛、大焰肩佛、杂色宝华严身佛、娑罗树王佛、宝华德佛、见一切义佛、如须弥山佛，像这样多如恒河沙数的诸佛，各在自己那一国里现出广长舌相，遍覆三千大千世界，说诚实的话：‘你们这些众生，应当信受这部赞叹不可思议功德、一切诸佛所护念的经。’”</p></div><div class="su-pair"><p class="su-org">“舍利弗！于汝意云何？何故名为‘一切诸佛所护念经’？舍利弗！若有善男子、善女人，闻是经受持者，及闻诸佛名者；是诸善男子、善女人，皆为一切诸佛之所护念，皆得不退转于阿耨多罗三藐三菩提。是故舍利弗！汝等皆当信受我语及诸佛所说。”</p><p class="su-tra">“舍利弗！你的意思怎么样？这部经为什么名叫‘一切诸佛所护念经’？舍利弗！如果有善男子、善女人听见这部经能领受奉行，以及听见诸佛名号的，这些善男子、善女人都被一切诸佛所护念，都能在无上正等正觉上不再退转。所以，舍利弗！你们大家都应当信受我说的话和诸佛所说的话。”</p></div><div class="su-pair"><p class="su-org">“舍利弗！若有人已发愿、今发愿、当发愿，欲生阿弥陀佛国者；是诸人等，皆得不退转于阿耨多罗三藐三菩提，于彼国土若已生、若今生、若当生。是故舍利弗！诸善男子、善女人若有信者，应当发愿生彼国土。”</p><p class="su-tra">“舍利弗！如果有人已经发愿、现在发愿、将来发愿，愿意生到阿弥陀佛的国土，这些人都能在无上正等正觉上不再退转：在那国土里，或者已经往生、或者现在往生、或者将来往生。所以，舍利弗！善男子、善女人只要信的，就应当发愿生彼国土。”</p></div><div class="su-pair"><p class="su-org">“舍利弗！如我今者，称赞诸佛不可思议功德；彼诸佛等，亦称赞我不可思议功德，而作是言：‘释迦牟尼佛能为甚难希有之事，能于娑婆国土五浊恶世，劫浊、见浊、烦恼浊、众生浊、命浊中，得阿耨多罗三藐三菩提，为诸众生说是一切世间难信之法。’舍利弗！当知我于五浊恶世行此难事，得阿耨多罗三藐三菩提，为一切世间说此难信之法，是为甚难！”</p><p class="su-tra">“舍利弗！就像我现在这样赞叹诸佛不可思议的功德，那些佛也照样赞叹我不可思议的功德，而这样说：‘释迦牟尼佛能做极难、极少有的事——能在娑婆国土这个五浊恶世，在劫浊、见浊、烦恼浊、众生浊、命浊之中，证得无上正等正觉，为诸众生说这一切世间难信之法。’舍利弗！应当知道，我在五浊恶世行这个难做的事，证得无上正等正觉，为一切世间说这难信之法，这是最难的了！”</p></div><div class="su-pair"><p class="su-org">佛说此经已，舍利弗及诸比丘，一切世间天、人、阿修罗等，闻佛所说，欢喜信受，作礼而去。</p><p class="su-tra">佛说完这部经，舍利弗和诸比丘，以及一切世间的天、人、阿修罗等，听了佛所说的，都欢喜信受，向佛行礼而去。</p></div></div></div>',4)])])}const n=a(l,[["render",c]]);export{g as __pageData,n as default};
